# Images and fonts: the bodies .AGI and .AGF reach, through the agn oracle (tests/oracle/oracle_agn.cpp), which loads every real file of both and calls the rest directly.
# Dropped as equivalent, each with its reason:
#   * FindCharacter's test that the bounds have not crossed before it returns a match: the loop's own test has just shown they have not, and the first pass starts with low 0 and high at least 0.
#   * FindCharacter's "here > code" as ">=": equality has returned already.
#   * The cast of an image's MatAssignment to 16 bits: the member is 16 bits, so the store narrows it anyway. Its effect on the range test is a mutant below.
#   * The deleting destructors' delete: compiler-made, and on the host the slot is the derived test class's.
I = "AtImage.cpp"
F = "AtFont.cpp"

